import { databaseCases as previous } from './quality-database-cases.mjs';

export const boundaryExpressions = [
  ['decode-text-null', "DECODE(CAST(NULL AS VARCHAR2(10)),CAST(NULL AS VARCHAR2(10)),1,2)"],
  ['decode-text-empty', "DECODE(NULL,CAST('' AS VARCHAR2(10)),1,2)"],
  ['decode-date-null', "DECODE(CAST(NULL AS DATE),CAST(NULL AS DATE),1,2)"],
  ['decode-search-function', "DECODE(CAST(NULL AS VARCHAR2(10)),TRIM(' '),1,2)"],
  ['decode-later-null', "DECODE(CAST(NULL AS VARCHAR2(10)),'x',1,CAST(NULL AS VARCHAR2(10)),2,3)"],
  ['decode-text-value', "DECODE(CAST('x' AS VARCHAR2(10)),CAST('x' AS VARCHAR2(10)),1,2)"],
  ['decode-fraction-search', "DECODE('.5',.5,1,2)"],
  ['nvl-fraction', "NVL(CAST(NULL AS VARCHAR2(20)),.5)"],
  ['nvl-negative-fraction', "NVL(CAST(NULL AS VARCHAR2(20)),-.5)"],
  ['nvl2-fraction', "NVL2(NULL,'x',.5)"],
  ['decode-fraction-result', "DECODE(2,1,'x',.5)"],
  ['decode-fraction-pair', "DECODE(2,1,'x',2,.5,'y')"],
  ['to-char-trunc', 'TO_CHAR(TRUNC(.55,1))'],
  ['to-char-round', 'TO_CHAR(ROUND(.55,1))'],
  ['to-char-abs', 'TO_CHAR(ABS(-.5))'],
  ['to-char-mod', 'TO_CHAR(MOD(1.5,1))'],
  ['to-char-power', 'TO_CHAR(POWER(.5,2))'],
  ['to-char-null-round', 'TO_CHAR(ROUND(CAST(NULL AS NUMBER),2))'],
  ['to-char-nested-numeric', 'TO_CHAR(ROUND(ABS(-.125),2)+TRUNC(.55,1))'],
  ['concat-null-number', "'A'||CAST(NULL AS NUMBER)"],
  ['concat-null-number-left', "CAST(NULL AS NUMBER)||'A'"],
  ['concat-fraction', ".5||'x'"],
  ['concat-numeric-pair', '.5||-.25'],
  ['concat-all-null', 'CAST(NULL AS NUMBER)||NULL'],
  ['concat-precedence-left', "'2'||3+4"],
  ['concat-precedence-right', "3+4||'x'"],
  ['concat-precedence-chain', "'2'||3+4||'x'"],
  ['arithmetic-text-product', "'2'*'3'"],
  ['arithmetic-empty-product', "''*'3'"],
  ['arithmetic-text-division', "'1'/'2'"],
  ['date-difference', "DATE '2024-01-02'-DATE '2024-01-01'"],
  ['date-difference-negative', "DATE '2024-01-01'-DATE '2024-01-03'"],
  ['date-difference-null', "CAST(NULL AS DATE)-DATE '2024-01-01'"],
  ['date-difference-format', "TO_CHAR((DATE '2024-01-02'-DATE '2024-01-01')/2)"],
  ['date-difference-time', "TO_DATE('2024-01-02 12:00:00','YYYY-MM-DD HH24:MI:SS')-TO_DATE('2024-01-01 00:00:00','YYYY-MM-DD HH24:MI:SS')"],
  ['date-difference-trunc', "TRUNC(DATE '2024-01-03')-TRUNC(DATE '2024-01-01')"],
  ['date-difference-dst', "DATE '2024-03-11'-DATE '2024-03-10'"],
];

export const databaseCases = [
  ...previous,
  ...boundaryExpressions.map(([id, expression]) => ({
    id: `boundary-${id}`,
    source: `SELECT ${expression} AS value FROM DUAL`,
    ...(id === 'date-difference-dst' ? { timezone: 'America/New_York' } : {}),
  })),
];
